package service;
import database.DatabaseConnection; import model.*; import org.mindrot.jbcrypt.BCrypt; import java.math.*; import java.sql.*; import java.time.*; import java.util.*; import org.slf4j.Logger; import org.slf4j.LoggerFactory;
/** Database-backed banking operations. Financial updates and ledger entries commit atomically. */
public class BankingService {
 private static final Logger LOG=LoggerFactory.getLogger(BankingService.class);
 private final Clock clock; private final BigDecimal limit;
 public BankingService(){this(Clock.systemDefaultZone(),new BigDecimal(System.getenv().getOrDefault("BANKING_DAILY_LIMIT","20000.00")));}
 public BankingService(Clock c,BigDecimal l){clock=c;limit=l.setScale(2);}
 public String createAccount(String name,String address,String mobile,AccountType type,BigDecimal initial,String pin){new Customer(1,name,address,mobile,"",LocalDateTime.now(clock)); if(pin==null||!pin.matches("[0-9]{4,6}"))throw new IllegalArgumentException("PIN must be 4 to 6 digits."); BigDecimal opening=initial==null?BigDecimal.ZERO:initial.setScale(2);if(opening.signum()<0)throw new IllegalArgumentException("Invalid initial deposit.");if(type==null)throw new IllegalArgumentException("Select an account type.");BigDecimal minimum=type==AccountType.SAVINGS?new BigDecimal("500.00"):new BigDecimal("1000.00");if(opening.signum()>0&&opening.compareTo(minimum)<0)throw new IllegalArgumentException("Minimum opening deposit for "+type+" is ₹"+minimum);String no=String.format("%012d",new java.security.SecureRandom().nextLong(1_000_000_000L,999_999_999_999L));
 try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO customers(full_name,address,mobile_number,pin_hash,created_at) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name.trim());p.setString(2,address.trim());p.setString(3,mobile.trim());p.setString(4,BCrypt.hashpw(pin,BCrypt.gensalt(12)));p.setTimestamp(5,Timestamp.valueOf(LocalDateTime.now(clock)));p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();id=k.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO accounts(account_number,customer_id,account_type,balance,status,opening_date,daily_withdrawal_limit) VALUES(?,?,?,?,'ACTIVE',?,?)")){p.setString(1,no);p.setLong(2,id);p.setString(3,type.name());p.setBigDecimal(4,opening);p.setDate(5,java.sql.Date.valueOf(LocalDate.now(clock)));p.setBigDecimal(6,limit);p.executeUpdate();}if(opening.signum()>0)insert(c,no,TransactionType.OPENING,opening,opening,null);c.commit();return no;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){LOG.error("Account creation failed",e);throw new IllegalStateException("Account creation failed; check database setup.",e);}}
 public String createAccount(String n,String a,String m,AccountType t,String pin){return createAccount(n,a,m,t,BigDecimal.ZERO,pin);}
 public BankTransaction deposit(String a,BigDecimal n,String pin){return change(a,n,TransactionType.DEPOSIT,pin);} public BankTransaction withdraw(String a,BigDecimal n,String pin){return change(a,n,TransactionType.WITHDRAWAL,pin);}
 private BankTransaction change(String no,BigDecimal raw,TransactionType type,String pin){BigDecimal n=positive(raw);try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{Row a=lock(c,no);active(a);auth(a,pin);if(type==TransactionType.WITHDRAWAL){BigDecimal spent;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE account_number=? AND transaction_type IN ('WITHDRAWAL','TRANSFER_OUT') AND DATE(transaction_timestamp)=?")){p.setString(1,no);p.setDate(2,java.sql.Date.valueOf(LocalDate.now(clock)));try(ResultSet r=p.executeQuery()){r.next();spent=r.getBigDecimal(1);}}WithdrawalPolicy.requireWithinLimit(a.limit,spent,n);if(a.balance.compareTo(n)<0)throw new IllegalArgumentException("Insufficient balance.");}BigDecimal b=type==TransactionType.DEPOSIT?a.balance.add(n):a.balance.subtract(n);update(c,no,b);BankTransaction tx=insert(c,no,type,n,b,null);c.commit();return tx;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){LOG.error("Transaction failed",e);throw new IllegalStateException("Transaction failed.",e);}}
 public String transfer(String from,String to,BigDecimal raw,String pin){if(from.equals(to))throw new IllegalArgumentException("Accounts must differ.");BigDecimal n=positive(raw);try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{String x=from.compareTo(to)<0?from:to,y=from.compareTo(to)<0?to:from;Row r1=lock(c,x),r2=lock(c,y),src=from.equals(x)?r1:r2,dst=to.equals(x)?r1:r2;active(src);active(dst);auth(src,pin);BigDecimal used;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE account_number=? AND transaction_type IN ('WITHDRAWAL','TRANSFER_OUT') AND DATE(transaction_timestamp)=?")){p.setString(1,from);p.setDate(2,java.sql.Date.valueOf(LocalDate.now(clock)));try(ResultSet z=p.executeQuery()){z.next();used=z.getBigDecimal(1);}}WithdrawalPolicy.requireWithinLimit(src.limit,used,n);if(src.balance.compareTo(n)<0)throw new IllegalArgumentException("Insufficient balance.");String ref=UUID.randomUUID().toString();BigDecimal sb=src.balance.subtract(n),db=dst.balance.add(n);update(c,from,sb);update(c,to,db);insert(c,from,TransactionType.TRANSFER_OUT,n,sb,ref);insert(c,to,TransactionType.TRANSFER_IN,n,db,ref);c.commit();return ref;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){LOG.error("Transfer failed",e);throw new IllegalStateException("Transfer failed.",e);}}
 public record AccountInfo(String accountNumber,String customerName,String address,String mobile,AccountType type,BigDecimal balance,AccountStatus status,LocalDate openingDate){}
 public AccountInfo accountInfo(String no,String pin){try(Connection c=DatabaseConnection.getConnection()){Row r=read(c,no);auth(r,pin);try(PreparedStatement p=c.prepareStatement("SELECT c.full_name,c.address,c.mobile_number,a.opening_date FROM accounts a JOIN customers c ON c.customer_id=a.customer_id WHERE a.account_number=?")){p.setString(1,no);try(ResultSet x=p.executeQuery()){x.next();return new AccountInfo(no,x.getString(1),x.getString(2),x.getString(3),r.type,r.balance,r.status,x.getDate(4).toLocalDate());}}}catch(SQLException e){throw new IllegalStateException("Account lookup failed.",e);}}
 public void changePin(String no,String oldPin,String newPin){if(newPin==null||!newPin.matches("[0-9]{4,6}"))throw new IllegalArgumentException("PIN must be 4 to 6 digits.");try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{Row r=lock(c,no);auth(r,oldPin);try(PreparedStatement p=c.prepareStatement("UPDATE customers SET pin_hash=? WHERE customer_id=?")){p.setString(1,BCrypt.hashpw(newPin,BCrypt.gensalt(12)));p.setLong(2,r.customer);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("PIN change failed.",e);}}
 public void updateCustomer(String no,String pin,String name,String address,String mobile){new Customer(1,name,address,mobile,"",LocalDateTime.now(clock));try(Connection c=DatabaseConnection.getConnection()){Row r=read(c,no);auth(r,pin);try(PreparedStatement p=c.prepareStatement("UPDATE customers SET full_name=?,address=?,mobile_number=? WHERE customer_id=?")){p.setString(1,name.trim());p.setString(2,address.trim());p.setString(3,mobile.trim());p.setLong(4,r.customer);p.executeUpdate();}}catch(SQLException e){throw new IllegalStateException("Customer update failed.",e);}}
 public void closeAccount(String no,String pin){try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{Row r=lock(c,no);auth(r,pin);if(r.balance.signum()!=0)throw new IllegalStateException("Balance must be zero to close the account.");try(PreparedStatement p=c.prepareStatement("UPDATE accounts SET status='CLOSED' WHERE account_number=?")){p.setString(1,no);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("Account closure failed.",e);}} public BigDecimal balance(String no,String pin){try(Connection c=DatabaseConnection.getConnection()){Row r=read(c,no);active(r);auth(r,pin);return r.balance;}catch(SQLException e){throw new IllegalStateException("Account lookup failed.",e);}}
 public List<BankTransaction> history(String no,String pin,LocalDate from,LocalDate to){if(from.isAfter(to))throw new IllegalArgumentException("Invalid date range.");try(Connection c=DatabaseConnection.getConnection()){Row a=read(c,no);active(a);auth(a,pin);List<BankTransaction> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT transaction_id,account_number,transaction_type,amount,transaction_timestamp,balance_after,reference_number FROM transactions WHERE account_number=? AND transaction_timestamp>=? AND transaction_timestamp<? ORDER BY ledger_order")){p.setString(1,no);p.setTimestamp(2,Timestamp.valueOf(from.atStartOfDay()));p.setTimestamp(3,Timestamp.valueOf(to.plusDays(1).atStartOfDay()));try(ResultSet r=p.executeQuery()){while(r.next())out.add(new BankTransaction(r.getString(1),r.getString(2),TransactionType.valueOf(r.getString(3)),r.getBigDecimal(4),r.getTimestamp(5).toLocalDateTime(),r.getBigDecimal(6),r.getString(7)));}}return out;}catch(SQLException e){throw new IllegalStateException("History lookup failed.",e);}}
 public BigDecimal withdrawalAllowance(String no,String pin){try(Connection c=DatabaseConnection.getConnection()){Row a=read(c,no);active(a);auth(a,pin);BigDecimal spent;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE account_number=? AND transaction_type IN ('WITHDRAWAL','TRANSFER_OUT') AND DATE(transaction_timestamp)=?")){p.setString(1,no);p.setDate(2,java.sql.Date.valueOf(LocalDate.now(clock)));try(ResultSet r=p.executeQuery()){r.next();spent=r.getBigDecimal(1);}}return WithdrawalPolicy.remaining(a.limit,spent).setScale(2);}catch(SQLException e){throw new IllegalStateException("Withdrawal allowance lookup failed.",e);}} public BigDecimal annualInterestEstimate(String no,String pin){BigDecimal rate=new BigDecimal(System.getenv().getOrDefault("SAVINGS_ANNUAL_RATE","0.04"));if(rate.signum()<0||rate.compareTo(BigDecimal.ONE)>0)throw new IllegalArgumentException("Savings interest rate must be between 0 and 1.");try(Connection c=DatabaseConnection.getConnection()){Row a=read(c,no);active(a);auth(a,pin);if(a.type!=AccountType.SAVINGS)throw new IllegalArgumentException("Interest estimates are available for savings accounts only.");return a.balance.multiply(rate).setScale(2,java.math.RoundingMode.HALF_UP);}catch(SQLException e){throw new IllegalStateException("Interest estimate failed.",e);}} public BigDecimal balanceBefore(String no,String pin,LocalDate day){try(Connection c=DatabaseConnection.getConnection()){Row a=read(c,no);active(a);auth(a,pin);try(PreparedStatement p=c.prepareStatement("SELECT balance_after FROM transactions WHERE account_number=? AND transaction_timestamp<? ORDER BY transaction_timestamp DESC,ledger_order DESC LIMIT 1")){p.setString(1,no);p.setTimestamp(2,Timestamp.valueOf(day.atStartOfDay()));try(ResultSet r=p.executeQuery()){return r.next()?r.getBigDecimal(1):BigDecimal.ZERO;}}}catch(SQLException e){throw new IllegalStateException("Opening balance lookup failed.",e);}} private record Row(String no,long customer,AccountType type,BigDecimal balance,AccountStatus status,BigDecimal limit,String hash){}
 private Row read(Connection c,String no)throws SQLException{return row(c,no,false);} private Row lock(Connection c,String no)throws SQLException{return row(c,no,true);}
 private Row row(Connection c,String no,boolean lock)throws SQLException{String q="SELECT a.account_number,a.customer_id,a.account_type,a.balance,a.status,a.daily_withdrawal_limit,c.pin_hash FROM accounts a JOIN customers c ON c.customer_id=a.customer_id WHERE a.account_number=?"+(lock?" FOR UPDATE":"");try(PreparedStatement p=c.prepareStatement(q)){p.setString(1,no);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Account not found.");return new Row(r.getString(1),r.getLong(2),AccountType.valueOf(r.getString(3)),r.getBigDecimal(4),AccountStatus.valueOf(r.getString(5)),r.getBigDecimal(6),r.getString(7));}}}
 private void active(Row r){if(r.status!=AccountStatus.ACTIVE)throw new IllegalStateException("Account is closed.");}private void auth(Row r,String pin){if(pin==null||!BCrypt.checkpw(pin,r.hash))throw new SecurityException("Authorization failed.");}private BigDecimal positive(BigDecimal a){if(a==null||a.scale()>2||a.signum()<=0)throw new IllegalArgumentException("Amount must be positive with at most two decimals.");return a.setScale(2);}
 private void update(Connection c,String no,BigDecimal b)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE accounts SET balance=? WHERE account_number=?")){p.setBigDecimal(1,b);p.setString(2,no);p.executeUpdate();}}
 private BankTransaction insert(Connection c,String no,TransactionType t,BigDecimal n,BigDecimal b,String ref)throws SQLException{String id=UUID.randomUUID().toString();LocalDateTime dt=LocalDateTime.now(clock);try(PreparedStatement p=c.prepareStatement("INSERT INTO transactions(transaction_id,account_number,transaction_type,amount,transaction_timestamp,balance_after,reference_number) VALUES(?,?,?,?,?,?,?)")){p.setString(1,id);p.setString(2,no);p.setString(3,t.name());p.setBigDecimal(4,n);p.setTimestamp(5,Timestamp.valueOf(dt));p.setBigDecimal(6,b);p.setString(7,ref);p.executeUpdate();}return new BankTransaction(id,no,t,n,dt,b,ref);}
}





